<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Calendar invitation</title><?php echo app('Illuminate\Foundation\Vite')(['resources/css/app.css']); ?></head><body><main class="guest-calendar-card"><h1><?php echo e($attendee->event->title); ?></h1><p><?php echo e($attendee->event->starts_at->setTimezone($attendee->event->timezone)->format('D, d M Y g:i A T')); ?></p><?php if(session('status')): ?><p><?php echo e(session('status')); ?></p><?php endif; ?><form method="POST" action="<?php echo e(request()->fullUrl()); ?>"><?php echo csrf_field(); ?> <?php $__currentLoopData = ['accepted'=>'Accept','tentative'=>'Tentative','declined'=>'Decline']; $__env->addLoop($__currentLoopData); foreach($__currentLoopData as $value=>$label): $__env->incrementLoopIndices(); $loop = $__env->getLastLoop(); ?><button name="response" value="<?php echo e($value); ?>" type="submit"><?php echo e($label); ?></button><?php endforeach; $__env->popLoop(); $loop = $__env->getLastLoop(); ?></form></main></body></html>
